begin; alter table public.portfolio_shares add column if not exists is_active boolean not null default true; alter table public.portfolio_shares add column if not exists paid_amount numeric(14,2); update public.portfolio_shares s set paid_amount = case when s.mode = 'percent' then round(coalesce(f.real_profit,0) * s.value / 100,2) else s.value end from public.portfolio_financial_summary f where s.is_paid and s.paid_amount is null; alter table public.portfolio_shares drop constraint if exists portfolio_shares_paid_snapshot; alter table public.portfolio_shares add constraint portfolio_shares_paid_snapshot check ((not is_paid and paid_on is null and paid_amount is null) or (is_paid and paid_amount is not null and paid_amount >= 0)); revoke insert, update, delete on public.portfolio_shares from authenticated; drop policy if exists portfolio_shares_member on public.portfolio_shares; create policy portfolio_shares_member on public.portfolio_shares for select to authenticated using ((select private.is_active_member())); create or replace function public.distribution_metrics(p_q text default null,p_activity text default null,p_payment text default null) returns table(result numeric,paid numeric,pending numeric,assigned numeric,available numeric) language sql security definer set search_path='' as $$ with filtered as (select s.* from public.portfolio_shares s where (p_q is null or public.normalize_text(s.participant) like '%' || public.normalize_text(p_q) || '%') and (p_activity is null or (p_activity='active' and s.is_active) or (p_activity='inactive' and not s.is_active)) and (p_payment is null or (p_payment='paid' and s.is_paid) or (p_payment='pending' and not s.is_paid))), totals as (select f.real_profit::numeric result,coalesce(sum(s.paid_amount) filter(where s.is_paid),0)::numeric paid,coalesce(sum(case when s.is_active and not s.is_paid then case when s.mode='percent' then f.real_profit*s.value/100 else s.value end else 0 end),0)::numeric pending from public.portfolio_financial_summary f left join filtered s on true group by f.real_profit) select result,paid,pending,paid+pending,result-paid-pending from totals $$; revoke all on function public.distribution_metrics(text,text,text) from public,anon; grant execute on function public.distribution_metrics(text,text,text) to authenticated; commit;
